from __future__ import annotations

import secrets

from fastapi import APIRouter
from fastapi.responses import HTMLResponse

router = APIRouter(tags=["user-workspace"])


@router.get("/app", response_class=HTMLResponse, include_in_schema=False)
def workspace() -> HTMLResponse:
    nonce = secrets.token_urlsafe(18)
    document = r'''<!doctype html>
<html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>X1 — рабочее пространство</title>
<style nonce="__NONCE__">
:root{--bg:#090b10;--side:#0e1118;--card:#131821;--line:#252b36;--text:#f4f6fa;--muted:#9aa5b4;--accent:#d34747;--ok:#66d394;--warn:#f0bf66;--bad:#ff8383;--code:#0c1016}*{box-sizing:border-box}html,body{height:100%}body{margin:0;background:var(--bg);color:var(--text);font:15px/1.55 Inter,system-ui,-apple-system,Segoe UI,Arial,sans-serif;overflow:hidden}button,select,textarea{font:inherit}button{cursor:pointer}.shell{height:100%;display:grid;grid-template-columns:270px 1fr}aside{background:var(--side);border-right:1px solid var(--line);padding:16px;display:flex;flex-direction:column;min-width:0}.brand{font-weight:850;letter-spacing:.08em;padding:8px 4px 18px}.new{width:100%;padding:11px;border:1px solid var(--line);background:#181d27;color:#fff;border-radius:11px;font-weight:700}.history{overflow:auto;margin:14px -5px;flex:1;padding:0 5px}.conv{width:100%;text-align:left;border:0;background:transparent;color:#dfe4ec;padding:10px;border-radius:9px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.conv:hover,.conv.active{background:#1b202a}.account{border-top:1px solid var(--line);padding-top:12px;color:var(--muted);font-size:13px}.account-row{display:flex;justify-content:space-between;gap:8px;align-items:center}.linkbtn{background:transparent;border:0;color:#d7dce5;padding:5px}main{min-width:0;display:flex;flex-direction:column;height:100%}header{min-height:62px;border-bottom:1px solid var(--line);display:flex;align-items:center;gap:10px;padding:8px 18px;flex-wrap:wrap}select{background:#121720;color:#fff;border:1px solid var(--line);border-radius:9px;padding:8px 10px}.spacer{flex:1}.health,.budget{font-size:12px;color:var(--muted);white-space:nowrap}.budget.warn{color:var(--warn)}.budget.bad{color:var(--bad)}.messages{flex:1;overflow:auto;padding:20px max(20px,calc((100% - 850px)/2));scroll-behavior:smooth}.older{display:block;margin:0 auto 20px;background:#121720;color:#dfe4ec;border:1px solid var(--line);border-radius:9px;padding:7px 12px}.empty{max-width:720px;margin:16vh auto 0;text-align:center}.empty h1{font-size:42px;margin:0 0 8px;letter-spacing:-.04em}.empty p{color:var(--muted);font-size:17px}.msg{max-width:820px;margin:0 auto 24px}.role{font-size:12px;text-transform:uppercase;letter-spacing:.08em;color:var(--muted);margin-bottom:7px}.bubble{overflow-wrap:anywhere}.user .bubble{white-space:pre-wrap;background:#171d27;border:1px solid var(--line);padding:13px 15px;border-radius:14px}.assistant .bubble{font-size:16px;line-height:1.68}.error .bubble{color:var(--bad)}.bubble p{margin:.55em 0}.bubble h1,.bubble h2,.bubble h3{line-height:1.25;margin:1.15em 0 .45em}.bubble h1{font-size:1.5em}.bubble h2{font-size:1.28em}.bubble h3{font-size:1.12em}.bubble ul,.bubble ol{padding-left:1.45em}.bubble blockquote{border-left:3px solid var(--line);margin:.8em 0;padding:.15em 0 .15em 1em;color:#cdd4df}.codewrap{position:relative;margin:12px 0;border:1px solid var(--line);background:var(--code);border-radius:11px;overflow:hidden}.codehead{display:flex;justify-content:space-between;align-items:center;padding:6px 9px;border-bottom:1px solid var(--line);font-size:12px;color:var(--muted)}.copy{background:#171d27;color:#e8edf5;border:1px solid var(--line);border-radius:7px;padding:4px 8px}.codewrap pre{margin:0;padding:13px;overflow:auto;white-space:pre;tab-size:4}.codewrap code{font:13px/1.55 ui-monospace,SFMono-Regular,Consolas,monospace}.tablewrap{overflow:auto;margin:12px 0;border:1px solid var(--line);border-radius:10px}.bubble table{border-collapse:collapse;min-width:100%}.bubble th,.bubble td{border-bottom:1px solid var(--line);border-right:1px solid var(--line);padding:8px 10px;text-align:left;vertical-align:top}.bubble th{background:#151b24}.meta{font-size:12px;color:var(--muted);margin-top:8px;display:flex;gap:8px;flex-wrap:wrap}.badge{border:1px solid var(--line);border-radius:999px;padding:2px 8px}.badge.supported{color:var(--ok)}.badge.unverified{color:var(--warn)}.badge.failed{color:var(--bad)}.sources{margin-top:10px;border:1px solid var(--line);border-radius:10px}.sources summary{cursor:pointer;padding:8px 10px;color:#dfe4ec}.source-list{padding:0 10px 10px}.source{padding:8px 0;border-top:1px solid var(--line)}.source a{color:#cbd8ff;text-decoration:none}.source small{display:block;color:var(--muted);overflow-wrap:anywhere}.composer-wrap{border-top:1px solid var(--line);padding:12px 20px 16px;background:linear-gradient(180deg,rgba(9,11,16,.82),#090b10)}.progress{max-width:850px;margin:0 auto 8px;display:flex;gap:6px;flex-wrap:wrap}.step{font-size:11px;color:#687384;border:1px solid var(--line);border-radius:999px;padding:2px 7px}.step.active{color:var(--warn);border-color:#6e5a32}.step.done{color:var(--ok)}.composer{max-width:850px;margin:auto;border:1px solid #303744;background:#121720;border-radius:16px;padding:11px}textarea{display:block;width:100%;resize:none;min-height:52px;max-height:190px;border:0;outline:0;background:transparent;color:#fff;padding:7px 8px}.composer-foot{display:flex;align-items:center;gap:9px;padding:4px}.send{margin-left:auto;background:var(--accent);color:white;border:0;border-radius:10px;padding:9px 16px;font-weight:750;min-width:104px}.send.stop{background:#8c3030}.send:disabled{opacity:.5;cursor:default}.state{font-size:12px;color:var(--muted);min-height:18px;max-width:850px;margin:7px auto 0}.retry{border:1px solid var(--line);background:#171d27;color:#fff;border-radius:8px;padding:5px 9px;margin-top:8px}.mobile-menu{display:none}@media(max-width:760px){.shell{grid-template-columns:1fr}aside{display:none;position:fixed;z-index:4;inset:0 22% 0 0;box-shadow:30px 0 80px #000}aside.open{display:flex}.mobile-menu{display:inline-block;background:transparent;border:1px solid var(--line);color:white;border-radius:8px;padding:6px 9px}header{padding:8px 10px;gap:6px}.budget{display:none}.messages{padding:16px 12px}.composer-wrap{padding:9px}.empty h1{font-size:34px}.msg{margin-bottom:19px}.bubble{font-size:15px!important}.codewrap pre{font-size:12px}.source small{font-size:11px}}
</style></head><body>
<div class="shell"><aside id="side"><div class="brand">X1 AI</div><button class="new" id="new-chat">+ Новый чат</button><div class="history" id="history"></div><div class="account"><div id="who">Проверяем аккаунт…</div><div class="account-row"><span>Локальная Qwen</span><button class="linkbtn" id="logout">Выйти</button></div></div></aside><main><header><button class="mobile-menu" id="menu">☰</button><select id="mode"><option value="auto">Авто</option><option value="fast">Fast</option><option value="work">Work</option><option value="deep">Deep</option></select><select id="verify"><option value="auto">Проверка: авто</option><option value="strict">Проверка: строгая</option><option value="off">Проверка: выкл</option></select><select id="web"><option value="auto">Интернет: авто</option><option value="always">Интернет: всегда</option><option value="off">Интернет: выкл</option></select><div class="spacer"></div><span class="budget" id="budget">Бюджет: …</span><span class="health" id="health">● X1</span></header><div class="messages" id="messages"><div class="empty" id="empty"><h1>Чем помочь?</h1><p>Локальная Qwen, проверяемые источники и прозрачные режимы работы.</p></div></div><div class="composer-wrap"><div class="progress" id="progress"></div><div class="composer"><textarea id="prompt" maxlength="200000" placeholder="Напишите сообщение…"></textarea><div class="composer-foot"><span class="health" id="counter"></span><button class="send" id="send">Отправить</button></div></div><div class="state" id="state"></div></div></main></div>
<script nonce="__NONCE__">
const token=sessionStorage.getItem('x1_access_token');if(!token)location.replace('/login');const $=id=>document.getElementById(id);const messages=$('messages'),state=$('state'),prompt=$('prompt'),send=$('send'),empty=$('empty');let conversationId=null,busy=false,activeController=null,stopRequested=false,oldestMessageAt=null,hasOlder=false,lastSubmission=null,currentSources=[];const steps=['queued','researching','thinking','generating','verifying'];
function setProgress(active){const root=$('progress');root.replaceChildren();for(const name of steps){const e=document.createElement('span');e.className='step';e.dataset.step=name;e.textContent={queued:'В очереди',researching:'Источники',thinking:'Обдумывание',generating:'Ответ',verifying:'Проверка'}[name];if(active){const ai=steps.indexOf(active),i=steps.indexOf(name);if(i<ai)e.classList.add('done');else if(i===ai)e.classList.add('active')}root.append(e)}}
function detailOf(data,status){const d=data&&data.detail;if(typeof d==='string')return d;if(d&&typeof d.message==='string')return d.message;if(d&&typeof d==='object'&&d.reason)return 'Сервис временно перегружен: '+d.reason+'. Повторите позже.';if(status===429)return 'Достигнут лимит. Повторите позже или выберите более лёгкий режим.';if(status===503)return 'Подсистема временно занята или восстанавливается.';return 'Запрос не выполнен.'}
async function api(path,options={},timeout=220000){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),timeout);try{const headers={...(options.headers||{}),Authorization:'Bearer '+token};if(options.body)headers['Content-Type']='application/json';const r=await fetch(path,{...options,headers,credentials:'omit',signal:controller.signal});let data=null;try{data=await r.json()}catch(_e){}if(r.status===401){sessionStorage.clear();location.replace('/login');throw new Error('Сессия завершена')}if(!r.ok){const e=new Error(detailOf(data,r.status));e.status=r.status;e.retryAfter=Number(r.headers.get('Retry-After')||0);throw e}return data}catch(e){if(e.name==='AbortError')throw new Error('Сервис отвечает слишком долго. Запрос остановлен.');throw e}finally{clearTimeout(timer)}}
function showBudget(data){const c=(data&&data.compute)||{},el=$('budget'),left=Math.max(0,Number(c.remaining_seconds||0)),limit=Math.max(0,Number(c.limit_seconds||0)),p=Number(c.utilization_percent||0);el.textContent='Бюджет: '+Math.round(left/60).toLocaleString('ru-RU')+' мин из '+Math.round(limit/60).toLocaleString('ru-RU');el.classList.toggle('warn',p>=70&&p<95);el.classList.toggle('bad',p>=95)}async function refreshBudget(){try{const d=await api('/v1/usage/budget',{},15000);showBudget(d)}catch(_e){}}
async function previewBudget(text){const d=await api('/v1/usage/budget-preview',{method:'POST',body:JSON.stringify({message:text,mode:$('mode').value,verification:$('verify').value,research_source_count:0})},15000);showBudget(d);if(d.projection&&d.projection.fits_remaining_compute===false)throw new Error('Запрос не помещается в оставшийся вычислительный бюджет. Выберите Fast/Auto.');return d}
function inlineText(parent,text){let rest=text;const re=/(`[^`]+`|\*\*[^*]+\*\*)/g;let m,pos=0;while((m=re.exec(rest))){if(m.index>pos)parent.append(document.createTextNode(rest.slice(pos,m.index)));const raw=m[0],el=document.createElement(raw.startsWith('`')?'code':'strong');el.textContent=raw.startsWith('`')?raw.slice(1,-1):raw.slice(2,-2);parent.append(el);pos=m.index+raw.length}if(pos<rest.length)parent.append(document.createTextNode(rest.slice(pos)))}
function renderMarkdown(target,text){target.replaceChildren();const lines=String(text||'').replace(/\r/g,'').split('\n');let i=0;while(i<lines.length){const line=lines[i];if(line.startsWith('```')){const lang=line.slice(3).trim().slice(0,30),buf=[];i++;while(i<lines.length&&!lines[i].startsWith('```'))buf.push(lines[i++]);if(i<lines.length)i++;const wrap=document.createElement('div');wrap.className='codewrap';const head=document.createElement('div');head.className='codehead';const lab=document.createElement('span');lab.textContent=lang||'код';const cp=document.createElement('button');cp.className='copy';cp.type='button';cp.textContent='Копировать';const code=buf.join('\n');cp.onclick=async()=>{try{await navigator.clipboard.writeText(code);cp.textContent='Скопировано';setTimeout(()=>cp.textContent='Копировать',1200)}catch(_e){cp.textContent='Не удалось'}};head.append(lab,cp);const pre=document.createElement('pre'),ce=document.createElement('code');ce.textContent=code;pre.append(ce);wrap.append(head,pre);target.append(wrap);continue}if(/^\s*\|.+\|\s*$/.test(line)&&i+1<lines.length&&/^\s*\|?\s*:?-{3,}/.test(lines[i+1])){const rows=[];rows.push(line);i+=2;while(i<lines.length&&/^\s*\|.+\|\s*$/.test(lines[i]))rows.push(lines[i++]);const wrap=document.createElement('div');wrap.className='tablewrap';const table=document.createElement('table');rows.forEach((r,ri)=>{const tr=document.createElement('tr');r.trim().replace(/^\||\|$/g,'').split('|').forEach(cell=>{const el=document.createElement(ri===0?'th':'td');inlineText(el,cell.trim());tr.append(el)});table.append(tr)});wrap.append(table);target.append(wrap);continue}const hm=line.match(/^(#{1,3})\s+(.+)/);if(hm){const h=document.createElement('h'+hm[1].length);inlineText(h,hm[2]);target.append(h);i++;continue}if(/^>\s?/.test(line)){const q=document.createElement('blockquote');inlineText(q,line.replace(/^>\s?/,''));target.append(q);i++;continue}if(/^[-*]\s+/.test(line)){const ul=document.createElement('ul');while(i<lines.length&&/^[-*]\s+/.test(lines[i])){const li=document.createElement('li');inlineText(li,lines[i].replace(/^[-*]\s+/,''));ul.append(li);i++}target.append(ul);continue}if(/^\d+\.\s+/.test(line)){const ol=document.createElement('ol');while(i<lines.length&&/^\d+\.\s+/.test(lines[i])){const li=document.createElement('li');inlineText(li,lines[i].replace(/^\d+\.\s+/,''));ol.append(li);i++}target.append(ol);continue}if(!line.trim()){i++;continue}const p=document.createElement('p');inlineText(p,line);target.append(p);i++}}
function attachSources(box,sources){const old=box.querySelector('.sources');if(old)old.remove();if(!sources||!sources.length)return;const d=document.createElement('details');d.className='sources';const s=document.createElement('summary');s.textContent='Источники · '+sources.length;const list=document.createElement('div');list.className='source-list';for(const src of sources){const row=document.createElement('div');row.className='source';const title=String(src.title||src.url||'Источник'),url=String(src.url||'');if(/^https?:\/\//i.test(url)){const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener noreferrer';a.textContent=title;row.append(a)}else{const t=document.createElement('span');t.textContent=title;row.append(t)}if(url){const small=document.createElement('small');small.textContent=url;row.append(small)}list.append(row)}d.append(s,list);box.append(d)}
function attachMeta(box,meta){const old=box.querySelector('.meta');if(old)old.remove();if(!meta)return;const m=document.createElement('div');m.className='meta';for(const [text,cls] of [[meta.quality?'Качество: '+meta.quality:'',meta.quality||''],[meta.mode||'',''],[meta.ttft!=null?'TTFT: '+Number(meta.ttft).toLocaleString('ru-RU')+' мс':'',''],[meta.tps!=null?Number(meta.tps).toFixed(1)+' ток/с':'','']])if(text){const x=document.createElement('span');x.className='badge '+cls;x.textContent=text;m.append(x)}if(m.childNodes.length)box.append(m)}
function add(role,text,meta=null,prepend=false){if(empty)empty.style.display='none';const box=document.createElement('div');box.className='msg '+role;const r=document.createElement('div');r.className='role';r.textContent=role==='user'?'Вы':role==='assistant'?'X1':'Ошибка';const b=document.createElement('div');b.className='bubble';if(role==='assistant')renderMarkdown(b,text);else b.textContent=text;box.append(r,b);attachMeta(box,meta);if(prepend){const first=[...messages.children].find(x=>x.classList&&x.classList.contains('msg'));messages.insertBefore(box,first||messages.firstChild)}else messages.append(box);return{box,bubble:b,text:String(text||'')}}
function addError(text,retryFn=null,retryAfter=0){const x=add('error',text);if(retryFn){const b=document.createElement('button');b.className='retry';b.type='button';b.textContent=retryAfter?'Повторить через '+retryAfter+' с':'Повторить';b.onclick=retryFn;x.box.append(b)}return x}
function setBusy(value,text='',canStop=false){busy=value;prompt.disabled=value;send.disabled=value&&!canStop;send.textContent=canStop?'Стоп':'Отправить';send.classList.toggle('stop',canStop);state.textContent=text}function stopActive(){if(activeController){stopRequested=true;activeController.abort();state.textContent='Останавливаю генерацию…'}}
async function ensureConversation(text){if(conversationId)return conversationId;const c=await api('/v1/conversations',{method:'POST',body:JSON.stringify({title:text.slice(0,100)})},30000);conversationId=c.id;await loadConversations();return c.id}
async function research(text,force=false){setProgress('researching');state.textContent=force?'Ищу источники…':'Проверяю актуальность…';const run=await api('/v1/research/runs',{method:'POST',body:JSON.stringify({question:text,intent:'general',max_results:10})},30000);if(!force&&((run.plan&&run.plan.freshness)||'stable')!=='current'){currentSources=[];return[]}await api('/v1/research/runs/'+encodeURIComponent(run.id)+'/discover',{method:'POST'},60000);const collected=await api('/v1/research/runs/'+encodeURIComponent(run.id)+'/collect',{method:'POST',body:JSON.stringify({max_sources:3})},90000);currentSources=(collected.sources||[]).slice(0,3);const ids=currentSources.map(x=>x.id).filter(Boolean);if(!ids.length)throw new Error('Поиск не дал проверяемых источников.');return ids}
function sseBlocks(buffer){const blocks=[];let index;while((index=buffer.indexOf('\n\n'))>=0){blocks.push(buffer.slice(0,index));buffer=buffer.slice(index+2)}return{blocks,buffer}}function decodeSse(block){let event='message';const data=[];for(const line of block.split('\n')){if(line.startsWith('event:'))event=line.slice(6).trim();else if(line.startsWith('data:'))data.push(line.slice(5).trimStart())}if(!data.length)return null;try{return{event,data:JSON.parse(data.join('\n'))}}catch(_e){return null}}
async function streamChat(body,live){const controller=new AbortController();activeController=controller;stopRequested=false;setProgress('queued');setBusy(true,'Запрос принят…',true);const headers={Authorization:'Bearer '+token,'Content-Type':'application/json',Accept:'text/event-stream'};let result=null,raw='';try{const r=await fetch('/v1/chat/stream',{method:'POST',headers,credentials:'omit',body:JSON.stringify(body),signal:controller.signal});if(!r.ok){let d=null;try{d=await r.json()}catch(_e){}const e=new Error(detailOf(d,r.status));e.retryAfter=Number(r.headers.get('Retry-After')||0);throw e}if(!r.body)throw new Error('Поток ответа недоступен.');const reader=r.body.getReader(),decoder=new TextDecoder();let buffer='';setProgress('thinking');while(true){const part=await reader.read();if(part.done)break;buffer+=decoder.decode(part.value,{stream:true}).replace(/\r\n/g,'\n');const parsed=sseBlocks(buffer);buffer=parsed.buffer;for(const block of parsed.blocks){const item=decodeSse(block);if(!item)continue;const d=item.data||{};if(item.event==='token'){setProgress('generating');raw+=typeof d.text==='string'?d.text:'';renderMarkdown(live.bubble,raw);messages.scrollTop=messages.scrollHeight}else if(item.event==='replace'){setProgress('verifying');raw=typeof d.text==='string'?d.text:raw;renderMarkdown(live.bubble,raw)}else if(item.event==='heartbeat'){if(!raw)setProgress(d.queue_waiting>0?'queued':'thinking');state.textContent=d.queue_waiting>0?'Ожидание безопасной очереди…':'X1 обрабатывает запрос…'}else if(item.event==='result'){setProgress('verifying');result=d}else if(item.event==='error'){const e=new Error(detailOf({detail:d.detail},d.status_code||500));e.retryAfter=Number(d.retry_after||0);throw e}}}if(!result)throw new Error('Поток завершился без финального результата.');return result}catch(e){if(e.name==='AbortError'&&stopRequested)return{cancelled:true};throw e}finally{activeController=null}}
async function submit(override=null){if(busy)return;const text=(override||prompt.value).trim();if(!text)return;lastSubmission=text;if(!override){prompt.value='';updateCounter();add('user',text)}setBusy(true,'Проверяю доступный ресурс…');setProgress('queued');let live=null;try{await previewBudget(text);const cid=await ensureConversation(text),webMode=$('web').value;let ids=[];currentSources=[];if(webMode==='always')ids=await research(text,true);else if(webMode==='auto')ids=await research(text,false);live=add('assistant','');const data=await streamChat({messages:[{role:'user',content:text}],conversation_id:cid,mode:$('mode').value,verification:$('verify').value,research_source_ids:ids},live);if(data.cancelled){state.textContent='Генерация остановлена. Полученный текст оставлен на экране.';setProgress(null);return}renderMarkdown(live.bubble,data.text||live.text);attachMeta(live.box,{quality:data.quality&&data.quality.status,mode:data.usage&&data.usage.mode,ttft:data.usage&&data.usage.ttft_ms,tps:data.usage&&data.usage.tokens_per_second});attachSources(live.box,currentSources);state.textContent=((data.quality&&data.quality.warnings)||[]).join(' · ');setProgress(null);await Promise.all([loadConversations(),refreshBudget()])}catch(e){if(live&&!live.bubble.textContent)live.box.remove();addError(e.message||'Ошибка запроса',()=>submit(text),e.retryAfter||0);state.textContent='Можно повторить запрос.';setProgress(null)}finally{setBusy(false,state.textContent);prompt.focus()}}
async function loadConversations(){try{const rows=await api('/v1/conversations?limit=30',{},30000),h=$('history');h.replaceChildren();for(const c of rows){const b=document.createElement('button');b.className='conv'+(c.id===conversationId?' active':'');b.textContent=c.title||'Новый чат';b.onclick=()=>openConversation(c.id);h.append(b)}}catch(_e){}}
function olderButton(){let b=$('older');if(!hasOlder){if(b)b.remove();return}if(!b){b=document.createElement('button');b.id='older';b.className='older';b.textContent='Загрузить более ранние сообщения';b.onclick=loadOlder;messages.prepend(b)}}
async function openConversation(id){if(busy)return;conversationId=id;messages.replaceChildren();const rows=await api('/v1/conversations/'+encodeURIComponent(id)+'/messages?limit=100',{},30000);for(const m of rows)add(m.role==='assistant'?'assistant':'user',m.content);oldestMessageAt=rows.length?rows[0].created_at:null;hasOlder=rows.length===100;olderButton();messages.scrollTop=messages.scrollHeight;await loadConversations();$('side').classList.remove('open')}
async function loadOlder(){if(!conversationId||!oldestMessageAt)return;const before=encodeURIComponent(oldestMessageAt),oldHeight=messages.scrollHeight,rows=await api('/v1/conversations/'+encodeURIComponent(conversationId)+'/messages?limit=100&before='+before,{},30000);for(let i=rows.length-1;i>=0;i--)add(rows[i].role==='assistant'?'assistant':'user',rows[i].content,null,true);oldestMessageAt=rows.length?rows[0].created_at:oldestMessageAt;hasOlder=rows.length===100;olderButton();messages.scrollTop=messages.scrollHeight-oldHeight}
function newChat(){if(busy)return;conversationId=null;messages.replaceChildren(empty);empty.style.display='block';oldestMessageAt=null;hasOlder=false;state.textContent='';setProgress(null);loadConversations();prompt.focus()}function updateCounter(){$('counter').textContent=prompt.value.length?prompt.value.length.toLocaleString('ru-RU')+' символов':''}
$('new-chat').onclick=newChat;send.onclick=()=>activeController?stopActive():submit();prompt.addEventListener('input',()=>{updateCounter();prompt.style.height='auto';prompt.style.height=Math.min(190,prompt.scrollHeight)+'px'});prompt.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();if(!busy)submit()}});$('menu').onclick=()=>$('side').classList.toggle('open');$('logout').onclick=async()=>{if(activeController)stopActive();try{await api('/v1/auth/logout',{method:'POST'},15000)}catch(_e){}sessionStorage.clear();location.replace('/login')};(async()=>{try{const me=await api('/v1/auth/me',{},20000);$('who').textContent=me.display_name||me.email;$('health').textContent='● '+(me.display_name||'X1');await Promise.all([loadConversations(),refreshBudget()]);prompt.focus()}catch(e){state.textContent=e.message}})();
</script></body></html>'''.replace("__NONCE__", nonce)
